struct Node;

/// Convert days since 1970-01-01 to a proleptic Gregorian (year, month, day).
/// Algorithm: Howard Hinnant's `civil_from_days`.
fn civil_from_unix_seconds(unix_secs: u64) -> (i64, u32, u32) {
    let days = (unix_secs / 86_400) as i64;
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097); // day of era, 0..=146096
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365; // year of era, 0..=399
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // day of year (Mar-based), 0..=365
    let mp = (5 * doy + 2) / 153; // month index (Mar=0), 0..=11
    let d = doy - (153 * mp + 2) / 5 + 1; // 1..=31
    let m = if mp < 10 { mp + 3 } else { mp - 9 }; // 1..=12
    let y = yoe + era * 400 + if m <= 2 { 1 } else { 0 };
    (y, m as u32, d as u32)
}

/// Format as `YYYY-MM-DD` (always exactly 10 characters).
fn format_date(unix_secs: u64) -> String {
    let (y, m, d) = civil_from_unix_seconds(unix_secs);
    if y > 9_999 {
        // Outside the four-digit range the contract's length guarantee covers;
        // clamp to the last representable day rather than emit an 11+ char date.
        return String::from("9999-12-31");
    }
    format!("{:04}-{:02}-{:02}", y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = crate::wasi::clocks::wall_clock::now();
        let started = now.seconds;
        let date = format_date(started);
        RunInfo { date, started }
    }
}

export!(Node);
